def checkXMatrix(grid):
    n = len(grid)
    for i in range(n):
        for j in range(n):
            # Check if on main or anti-diagonal
            if i == j or i + j == n - 1:
                # Diagonal cells must be non-zero
                if grid[i][j] == 0:
                    return False
            else:
                # Non-diagonal cells must be zero
                if grid[i][j] != 0:
                    return False
    return True
